// =============================================================================
// How this service words a request-validation refusal
// =============================================================================
//
// MediaPackage VOD answers a request whose MEMBERS do not validate with HTTP 422
// `UnprocessableEntityException` carrying, beside `message`, an `errors` map that
// attributes each violation to the input member it is about — or to `base` when the
// violation is about the request as a whole. The modelled shape declares only
// `Message`, so the map cannot be carried by the generated error type; it is carried
// by the synthetic shape below, which renders with the SAME error code and status as
// the modelled one.
//
// The two message builders under it word the failures the MODELLED errors carry:
// a resource the request named that does not exist, and one that already does. Both
// live here rather than in a handler so every operation words the same failure the
// same way (`lib.rs` is generated, so this crate cannot declare a module of its own).

/// The `errors` key a violation of the request AS A WHOLE is attributed to — as
/// opposed to one attributed to a single input member.
///
/// Recorded behaviour: a `CreatePackagingConfiguration` carrying more than one
/// package block is answered with `errors: {"base": [...]}`, because no single
/// member is at fault.
pub const BASE_ATTRIBUTE: &str = "base";

/// The wire error code a request-validation refusal is named by — the `__type` and the
/// `x-amzn-errortype` a client branches on.
///
/// The MODELLED shape's name: this envelope differs from the generated
/// `UnprocessableEntityException` only in carrying the `errors` member, so a client
/// cannot tell which of the two answered.
pub const UNPROCESSABLE_ENTITY_CODE: &str = "UnprocessableEntityException";

/// `UnprocessableEntityException`'s modelled `httpError`
/// (`smithy_query(query="shape",shape="UnprocessableEntityException")`: `errorKind
/// client`, `httpError 422`).
pub const UNPROCESSABLE_ENTITY_STATUS: u16 = 422;

/// The `message` member of the synthetic `UnprocessableEntityException` shape.
///
/// Named and `@jsonName`d exactly like the modelled
/// `UnprocessableEntityException$Message` (`jsonName: message`), so the body reads
/// the same to a client whichever of the two shapes answered.
static UNPROCESSABLE_MESSAGE: Schema = Schema::new_member(
    ShapeId::from_static(
        "smithy.framework#UnprocessableEntityWithErrors$message",
        "smithy.framework",
        "message",
    ),
    ShapeType::String,
    "message",
    0,
)
.with_xml_name("Message")
.with_json_name("message");

/// The `errors` member of the synthetic `UnprocessableEntityException` shape: a map
/// from an input member's wire name (or [`BASE_ATTRIBUTE`]) to the constraint
/// phrases that member violated.
static UNPROCESSABLE_ERRORS: Schema = Schema::new_member(
    ShapeId::from_static(
        "smithy.framework#UnprocessableEntityWithErrors$errors",
        "smithy.framework",
        "errors",
    ),
    ShapeType::Map,
    "errors",
    1,
)
.with_xml_name("Errors")
.with_json_name("errors");

/// Schema for the synthetic `UnprocessableEntityException` shape.
///
/// In the `smithy.framework` namespace for the same reason as `NotImplemented`: the
/// `errors` member is recorded behaviour the model does not declare, so there is no
/// modelled shape that can carry it and the synthetic one must not collide with a
/// modelled name. The wire error code is still
/// `UnprocessableEntityException` — it comes from [`OperationError::shape_name`]
/// below, not from this schema.
pub static UNPROCESSABLE_ENTITY_SCHEMA: Schema = Schema::new_struct(
    ShapeId::from_static(
        "smithy.framework#UnprocessableEntityWithErrors",
        "smithy.framework",
        "UnprocessableEntityWithErrors",
    ),
    ShapeType::Structure,
    &[&UNPROCESSABLE_MESSAGE, &UNPROCESSABLE_ERRORS],
);

/// A request whose members did not validate: the per-attribute `errors` map, and the
/// `message` that states the same attribution as one line of text.
#[derive(Debug, Clone)]
pub struct UnprocessableEntity {
    /// The violation as one line: `<member_name> <phrase>` for a member-level
    /// violation, `<ResourceType> <phrase>` for a whole-request one.
    pub message: String,
    /// The violated attribute (an input member's wire name, or [`BASE_ATTRIBUTE`])
    /// mapped to the constraint phrases it violated.
    pub errors: BTreeMap<String, Vec<String>>,
}

impl UnprocessableEntity {
    /// A violation of ONE input member: `errors` is `{<wire name>: [<phrase>]}` and
    /// the message is the member's name in snake case followed by the phrase.
    ///
    /// `member` is the member's WIRE name (its `@jsonName`, e.g. `packagingGroupId`),
    /// which is what a client keys its per-field rendering on; the message spells the
    /// same member in snake case (`packaging_group_id does not exist`). `phrase` is
    /// the constraint that was violated, stated as a verb phrase about the member
    /// (`does not exist`, `must not be empty`) and carrying no trailing period.
    pub fn member(member: &str, phrase: impl Into<String>) -> Self {
        let phrase = phrase.into();
        Self {
            message: format!("{} {phrase}", snake_case(member)),
            errors: BTreeMap::from([(member.to_string(), vec![phrase])]),
        }
    }

    /// The same violation, worded with the FIXED sentence this service states for a
    /// refusal class instead of the composed `<member_name> <phrase>` line.
    ///
    /// Some refusal classes are worded by a sentence that interpolates nothing from
    /// the request, names no input member and echoes no offending value; the
    /// per-attribute `errors` map still attributes the violation to the member at
    /// fault, so a client rendering per field is unaffected. Reach for this only where
    /// the fixed wording is recorded, and keep [`Self::member`]'s composed line
    /// everywhere else.
    pub fn with_message(mut self, message: impl Into<String>) -> Self {
        self.message = message.into();
        self
    }

    /// Violations of SEVERAL input members in ONE refusal, or `None` when
    /// `violations` is empty — nothing was violated, so there is nothing to refuse.
    ///
    /// A request's parameters are validated TOGETHER, and the `errors` map is
    /// per-attribute, so a caller that sent two invalid members is told about both
    /// rather than fixing one to discover the other. Each entry is a member's WIRE
    /// name (dotted for a nested member, `authorization.secretsRoleArn`) and the
    /// constraint phrase it violated, worded exactly as [`Self::member`] words a
    /// single one; the message states each attribution in turn, separated by `, `.
    /// With one violation this produces precisely what [`Self::member`] does, so a
    /// client parses one form however many members were at fault.
    pub fn members(violations: Vec<(String, String)>) -> Option<Self> {
        if violations.is_empty() {
            return None;
        }
        let mut message = String::new();
        let mut errors: BTreeMap<String, Vec<String>> = BTreeMap::new();
        for (member, phrase) in violations {
            if !message.is_empty() {
                message.push_str(", ");
            }
            message.push_str(&snake_case(&member));
            message.push(' ');
            message.push_str(&phrase);
            errors.entry(member).or_default().push(phrase);
        }
        Some(Self { message, errors })
    }

    /// A violation of the request AS A WHOLE — no single member is at fault, so
    /// `errors` is keyed by [`BASE_ATTRIBUTE`] and the message names the resource
    /// type the request would have created instead of a member.
    pub fn request(resource: &str, phrase: impl Into<String>) -> Self {
        let phrase = phrase.into();
        Self {
            message: format!("{resource} {phrase}"),
            errors: BTreeMap::from([(BASE_ATTRIBUTE.to_string(), vec![phrase])]),
        }
    }
}

/// An input member's wire name (`packagingGroupId`) as the message spells it
/// (`packaging_group_id`).
fn snake_case(member: &str) -> String {
    let mut out = String::with_capacity(member.len() + 4);
    for ch in member.chars() {
        if ch.is_ascii_uppercase() {
            if !out.is_empty() {
                out.push('_');
            }
            out.push(ch.to_ascii_lowercase());
        } else {
            out.push(ch);
        }
    }
    out
}

/// The resource-type label every message about an Asset names that type by.
///
/// One constant per resource type, so the label cannot drift between the operations
/// that word a failure about the same resource; see
/// [`PACKAGING_CONFIGURATION_LABEL`] for why a label is not read off the modelled
/// shape name.
pub const ASSET_LABEL: &str = "Asset";

/// The resource-type label every message about a PackagingGroup names that type by;
/// see [`ASSET_LABEL`].
pub const PACKAGING_GROUP_LABEL: &str = "PackagingGroup";

/// The resource-type label every message about a PackagingConfiguration names that
/// type by.
///
/// NOT the modelled shape or operation noun: this API words its messages about this
/// one resource type with the abbreviation `PackagingConfig` — recorded both in the
/// not-found of an unheld id (`PackagingConfig with id=<id> not found`, behavioral
/// unit `mediapackage-vod.delete-packaging-configuration-state-transition`) and in
/// the conflict a duplicate create is refused with (`PackagingConfig with id=<id>
/// already exists`, behavioral unit
/// `mediapackage-vod.concurrent-packaging-configuration-duplicate-id-contention`).
/// Every message of this crate that names the type — the creates, the describe and
/// the delete, by `Id` or by ARN — takes it from here, so one resource type reads as
/// one noun whichever operation answered.
pub const PACKAGING_CONFIGURATION_LABEL: &str = "PackagingConfig";

/// The message a `NotFoundException` carries for a resource the request named and
/// this service holds none of: `<ResourceType> with id=<requested id> not found`.
///
/// Built from the id the REQUEST asked for, never from a stored record — there is no
/// stored record to read. `resource` is the label this service names that resource
/// type by in a message: [`ASSET_LABEL`], [`PACKAGING_GROUP_LABEL`] or
/// [`PACKAGING_CONFIGURATION_LABEL`], never a shape or operation name.
pub fn not_found_message(resource: &str, id: &str) -> String {
    format!("{resource} with id={id} not found")
}

/// The message the conflict refusal carries when a create re-uses an id this service
/// already holds: `<ResourceType> with id=<requested id> already exists`.
///
/// Same binding form as [`not_found_message`], and `resource` is the same per-type
/// label, so one resource type reads as one noun whether the request named an id
/// this service holds none of or one it already holds.
pub fn already_exists_message(resource: &str, id: &str) -> String {
    format!("{resource} with id={id} already exists")
}

/// An operation's error channel: either the synthetic scaffold signal, or one of the
/// operation's own modeled errors.
#[derive(Debug)]
pub enum Scaffolded<E> {
    /// The operation is generated but has no implementation. Renders as HTTP 501.
    NotImplemented(NotImplemented),
    /// A modeled error the operation declares. Renders with the model's own status.
    Modeled(E),
    /// A request whose members did not validate. Renders as HTTP 422 with the error
    /// code `UnprocessableEntityException` — the modelled status and code — plus the
    /// `errors` map the modelled shape cannot carry.
    Unprocessable(UnprocessableEntity),
    /// The request was refused as invalid. Renders as HTTP 400 with the error code
    /// `ValidationException`.
    ///
    /// On the JSON and CBOR protocols that is the same status and code the boundary
    /// validator answers with. Two differences are worth knowing, and neither is
    /// specific to this variant — every handler-returned error shares them:
    /// the awsJson families omit the `x-amzn-errortype` header that the boundary
    /// path sets, and the query protocols render a boundary refusal as
    /// `MalformedQueryString` rather than `ValidationException`, so a client
    /// matching on the error code there sees two codes for one logical failure.
    ValidationException(ValidationException),
}

impl<E> Scaffolded<E> {
    /// The scaffold signal for `operation`.
    pub fn not_implemented(operation: &str) -> Self {
        Self::NotImplemented(NotImplemented::new(operation))
    }

    /// Refuse the request as invalid, with HTTP 400 `ValidationException`.
    ///
    /// Reach for this when the request is wrong in a way the model cannot express,
    /// so the boundary validator passed it: a value outside a rule the service
    /// enforces but does not model, or a combination of members that cannot hold
    /// together. Answer it INSTEAD of `not_implemented` — a 501 says "nobody has
    /// written this yet", which is a different claim and is counted as one.
    ///
    /// If this service's model declares its own `ValidationException` (or another
    /// client-input error) use THAT: the modeled shape may carry members beyond
    /// `message` — a `reason`, a field list — and a real client reads them. When the
    /// operation already lists it, it is a plain variant on the generated error enum;
    /// `#[operation_error]`'s `extra_errors` is only for widening in a shape the
    /// SERVICE models that this OPERATION does not list.
    pub fn validation(message: impl Into<String>) -> Self {
        Self::ValidationException(ValidationException::new(message))
    }
}

/// Lets `?` and `.into()` lift a validation refusal — built by
/// [`UnprocessableEntity`], which names no operation — into ANY operation's error
/// channel, the way the per-operation `From<{Op}ErrorModeled>` impls lift a modelled
/// failure.
impl<E> From<UnprocessableEntity> for Scaffolded<E> {
    fn from(invalid: UnprocessableEntity) -> Self {
        Self::Unprocessable(invalid)
    }
}

impl std::fmt::Display for UnprocessableEntity {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "UnprocessableEntityException: {}", self.message)
    }
}

impl std::error::Error for UnprocessableEntity {}

impl SerializableStruct for UnprocessableEntity {
    fn serialize_members(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        s.write_string(&UNPROCESSABLE_MESSAGE, self.message.as_str())?;
        s.write_map(&UNPROCESSABLE_ERRORS, &|entries| {
            for (attribute, phrases) in &self.errors {
                entries.write_string(&UNPROCESSABLE_ERRORS, attribute.as_str())?;
                entries.write_list(&UNPROCESSABLE_ERRORS, &|elements| {
                    for phrase in phrases {
                        elements.write_string(&UNPROCESSABLE_ERRORS, phrase.as_str())?;
                    }
                    Ok(())
                })?;
            }
            Ok(())
        })?;
        Ok(())
    }
}

impl<E: std::fmt::Display> std::fmt::Display for Scaffolded<E> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::NotImplemented(e) => write!(f, "{e}"),
            Self::Modeled(e) => write!(f, "{e}"),
            Self::Unprocessable(e) => write!(f, "{e}"),
            Self::ValidationException(e) => write!(f, "{e}"),
        }
    }
}

/// `source()` forwards to the modeled error rather than taking the default `None`, so a
/// modeled error's own `source()` is preserved through the wrapper.
impl<E: std::error::Error + 'static> std::error::Error for Scaffolded<E> {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::NotImplemented(e) => e.source(),
            Self::Modeled(e) => e.source(),
            Self::Unprocessable(e) => e.source(),
            Self::ValidationException(e) => e.source(),
        }
    }
}

/// Every `OperationError` method delegates to the modeled error, so wrapping an
/// implemented operation's error channel changes NOTHING about how that error is
/// rendered. Only the synthetic variant behaves differently — and it is the one that
/// must answer 501.
impl<E: OperationError> OperationError for Scaffolded<E> {
    fn as_serializable(&self) -> &dyn SerializableStruct {
        match self {
            Self::NotImplemented(e) => e,
            Self::Modeled(e) => e.as_serializable(),
            Self::Unprocessable(e) => e,
            Self::ValidationException(e) => e,
        }
    }

    fn variant_schema(&self) -> &'static Schema {
        match self {
            Self::NotImplemented(_) => &NOT_IMPLEMENTED_SCHEMA,
            Self::Modeled(e) => e.variant_schema(),
            Self::Unprocessable(_) => &UNPROCESSABLE_ENTITY_SCHEMA,
            Self::ValidationException(_) => &VALIDATION_EXCEPTION_SCHEMA,
        }
    }

    /// The wire error code (`__type` on JSON/CBOR, `<Code>` on XML).
    ///
    /// Keep the literal as it is: changing it changes the wire error code clients match
    /// on. It is intentionally not tied to the Rust variant name.
    fn shape_name(&self) -> &'static str {
        match self {
            Self::NotImplemented(_) => "NotImplemented",
            Self::Modeled(e) => e.shape_name(),
            // The MODELLED error code: this variant differs from the generated
            // `UnprocessableEntityException` only in carrying the `errors` member,
            // so a client branching on the code cannot tell which one answered.
            Self::Unprocessable(_) => UNPROCESSABLE_ENTITY_CODE,
            Self::ValidationException(_) => "ValidationException",
        }
    }

    /// 501 for the scaffold signal.
    ///
    /// Keep it 501 and not a 5xx server fault: SDK retry classifiers treat those as
    /// retryable, so a client would retry an operation that can never succeed.
    fn http_status(&self) -> u16 {
        match self {
            Self::NotImplemented(_) => 501,
            Self::Modeled(e) => e.http_status(),
            // `UnprocessableEntityException`'s modelled `httpError`.
            Self::Unprocessable(_) => UNPROCESSABLE_ENTITY_STATUS,
            Self::ValidationException(_) => 400,
        }
    }

    fn query_error_code(&self) -> Option<&'static str> {
        match self {
            // No awsQuery code: the synthetic shape is not in the model, so there is
            // no `awsQueryError` trait to honour. The 501 + `<Code>NotImplemented`
            // envelope carries the signal on the query protocols too.
            Self::NotImplemented(_) => None,
            Self::Modeled(e) => e.query_error_code(),
            // Same reason: neither synthetic shape carries an `awsQueryError` trait
            // (and this service is restJson1, which has no query error code).
            Self::Unprocessable(_) => None,
            Self::ValidationException(_) => None,
        }
    }
}
